window.EXAM_PAPERS=window.EXAM_PAPERS||{};window.EXAM_PAPERS["1756567629"]={"id":"1756567629","title":"【英语部分】选词填空刷题题库","group":"专项练习","items":[{"id":"1718789648908","type":"single","material":"","stem":"it seems that the managers didn't take reasonable care in（）the unprofitable divisions.","options":[{"label":"A","content":"being restructured"},{"label":"B","content":"restructuring"},{"label":"C","content":"restructure"},{"label":"D","content":"restructured"}],"answer":"B","explanation":"介词（in）的后面应当使用名词形式。A 选项和 B 选项都有可能，但考虑到空格中应该填入充当宾语的名词，此处 应填入主动语态。A 选项是被动语态，是错误的。","no":1},{"id":"1718789648909","type":"single","material":"","stem":"The manager was（）for the damage caused by his staff's lack of care.","options":[{"label":"A","content":"respectful"},{"label":"B","content":"available"},{"label":"C","content":"resourceful"},{"label":"D","content":"responsible"}],"answer":"D","explanation":"be 动词的后面使用“形容词+介词”形式，往往考查的是固定搭配。be responsible for...对某事负责。","no":2},{"id":"1718789648910","type":"single","material":"","stem":"<p>The head of marketing was concerned（ &nbsp; ）the major change in the business environment.</p>","options":[{"label":"A","content":"to"},{"label":"B","content":"in"},{"label":"C","content":"that"},{"label":"D","content":"about"}],"answer":"D","explanation":"将其当作 “be+形容词”的固定搭配来记忆。be concerned about sth.意为“关心某事，记挂某事”","no":3},{"id":"1718789648911","type":"single","material":"","stem":"The floor manager, as well as his managerial staff,（）the customer's phone call.","options":[{"label":"A","content":"haven't returned"},{"label":"B","content":"hasn't been returned"},{"label":"C","content":"hasn't returned"},{"label":"D","content":"returning"}],"answer":"C","explanation":"因为句子中没有谓语动词。所以排除 D 选项。考虑到单复数的问题。排除 A 选项。后面有宾语，所以排除被动语 态 B 选项。","no":4},{"id":"1718789648912","type":"single","material":"","stem":"Its recent gains in market share can be（）to price cutting efforts.","options":[{"label":"A","content":"accounted"},{"label":"B","content":"attributed"},{"label":"C","content":"accused"},{"label":"D","content":"appraised"}],"answer":"B","explanation":"be 动词后面的动词应使用过去分词，也就是形容词的形式，空格后有 to ，所以应当考虑固定搭配。attribute A to B (=A is attributed to B)把 A  归因于 B （题目意在考查固定搭配的被动语态用法）","no":5},{"id":"1718789648913","type":"single","material":"","stem":"The company is involved in leasing 216,000 trucks and providing（）services for customers.","options":[{"label":"A","content":"able"},{"label":"B","content":"logistic"},{"label":"C","content":"eligible"},{"label":"D","content":"informative"}],"answer":"B","explanation":"leasing 和 provding 都和 be involved in 有关。本体考查及物动词（providing）和宾语（services）中间能够填入 的形容词。解题的提示在于 truck 一词。给顾客提供了什么服务呢？应当选 B 选项。即提供了物流服务。","no":6},{"id":"1718789648914","type":"single","material":"","stem":"His doctor suggested to him that he（）medication everyday.","options":[{"label":"A","content":"be taken"},{"label":"B","content":"takes"},{"label":"C","content":"take"},{"label":"D","content":"Took"}],"answer":"C","explanation":"suggest 一词是关键的解题提示。suggeset 有“主张、要求、命令、提议、忠告”等意思。that引导的从句中，动词 的前面省略了表示你“应该”这样做的 should，因此这里应该使用动词原形。由于后面有宾语，所以 A 选项是错误的。","no":7},{"id":"1718789648915","type":"single","material":"","stem":"We provide the prompt, efficient and high quality service consumers expect from（）.","options":[{"label":"A","content":"ourselves"},{"label":"B","content":"ours"},{"label":"C","content":"we"},{"label":"D","content":"us"}],"answer":"D","explanation":"介词的后面的人称代词应当用宾语形式。因此 D 选项是正确答案。实际上 ourselves 和 ours 也有可能用作宾格，但 为什么用在这里不对呢？ourselves 和动词（expect）的主体 consumers 不一致。ours 的意思是“我们的东西”，而这里 没有讲到“我们的东西”是什么。","no":8},{"id":"1718789648916","type":"single","material":"","stem":"<p>In Korea, the gross domestic product has increased（ &nbsp; ）a 3.2 percent rate in the past decade.</p>","options":[{"label":"A","content":"at"},{"label":"B","content":"for"},{"label":"C","content":"of"},{"label":"D","content":"in"}],"answer":"A","explanation":"凡是考查介词的题目，请务必注意它和后面名词的关系，后面的名词 rate 有“价格；速度；比率”的意思，且任 何一种意思通常都与 at 搭配使用。因为 at 具有可以数字搭配的属性","no":9},{"id":"1718789648917","type":"single","material":"","stem":"If every employee does his or her（）to ensure q quality product, this company will surely succeed.","options":[{"label":"A","content":"most"},{"label":"B","content":"almost"},{"label":"C","content":"utmost"},{"label":"D","content":"mostly"}],"answer":"C","explanation":"空格前是形容词性物主代词， 因此空格内应填入名词。同时也是考查固定搭配，因此 C 选项是正确答案。do one' s utmost 意为“尽某人的最大努力”。","no":10},{"id":"1718789648918","type":"single","material":"","stem":"You also may ask at any time to see the request data you（）us and request correction or deletion.","options":[{"label":"A","content":"given"},{"label":"B","content":"to be given"},{"label":"C","content":"have given"},{"label":"D","content":"have been given"}],"answer":"C","explanation":"名词（data）后有主语（you），因此应想到这里省略了引导定语从句的关系词。关系词是连词，you是主语，因此 空格内应填入谓语动词。C 选项和 D 选项都是谓语动词，此时应考虑是主动语态还是被动语态。give 是及物动词，us 是 间接宾语，省略了关系词可看做直接宾语。所以这里应当填入主动语态 C 选项。","no":11},{"id":"1718789648919","type":"single","material":"","stem":"（）you have already registered for the 2007 Forum, attend this free pre-forum class.","options":[{"label":"A","content":"Although"},{"label":"B","content":"Regarding"},{"label":"C","content":"As"},{"label":"D","content":"If"}],"answer":"D","explanation":"只要出现两个“S+V ”,就要考虑填入连词，B 选项是介词，应排除。剩下的都是引导状语从句的连词，答案就要通 过释义来判断。","no":12},{"id":"1718789648920","type":"single","material":"","stem":"We keep our clients informed of every（）matter influencing their rights.","options":[{"label":"A","content":"significant"},{"label":"B","content":"attractive"},{"label":"C","content":"prevalent"},{"label":"D","content":"reasonable"}],"answer":"A","explanation":"本题考查形容词的用法，因此要考虑和它修饰的名词（ matter ）的关系。要记住 significant 在这里是“重要的”的 意思。","no":13},{"id":"1718789648921","type":"single","material":"","stem":"We（）with all laws and regulations, applied in local and international society.","options":[{"label":"A","content":"apply"},{"label":"B","content":"comply"},{"label":"C","content":"account"},{"label":"D","content":"respond"}],"answer":"B","explanation":"空格后有介词， 因此应填入不及物动词， 同时与该介词形成固定搭配。comply with  意为“遵守 （要求、命令等）”。","no":14},{"id":"1718789648922","type":"single","material":"","stem":"The shopping mall intends to（）customers by renovating the mall itself.","options":[{"label":"A","content":"contact"},{"label":"B","content":"attend"},{"label":"C","content":"attract"},{"label":"D","content":"meet"}],"answer":"C","explanation":"空格后是名词，所以空格中应填入机务动词。仔细考虑与宾语的搭配，attract customers 意为“吸引顾客”。","no":15},{"id":"1718789648923","type":"single","material":"","stem":"The beauty of scenery in the falls gave a（）impression to us.","options":[{"label":"A","content":"lastingly"},{"label":"B","content":"last"},{"label":"C","content":"lasting"},{"label":"D","content":"lasted"}],"answer":"C","explanation":"冠词和名词的中间应填入形容词。此处的正确答案是 lasting impression ，意为“持久的印象”。","no":16},{"id":"1718789648924","type":"single","material":"","stem":"Attractive compensation（）with qualifications and experience will be offered to all successful candidates.","options":[{"label":"A","content":"eligible"},{"label":"B","content":"responsive"},{"label":"C","content":"commensurate"},{"label":"D","content":"adaptable"}],"answer":"C","explanation":"形容词放在名词后面修饰名词，省略了 which/who is。因此这里仍然是“be+形容词+介词”的形式。 be commensurate with 意为“与某物成比例”。","no":17},{"id":"1718789648925","type":"single","material":"","stem":"One thing you can count on is that the stock market almost never does（）you expect it to do.","options":[{"label":"A","content":"what"},{"label":"B","content":"because"},{"label":"C","content":"that"},{"label":"D","content":"why"}],"answer":"A","explanation":"空格内应填入引导名词从句的连词，从句做 does（及物动词）的宾语。另外，空格后的句子里没有do 的宾语， 是不完整的。因此填入 what 是正确的。","no":18},{"id":"1718789648926","type":"single","material":"","stem":"For the past（）months they have taking care of all new statistical information in the papers.","options":[{"label":"A","content":"several"},{"label":"B","content":"less"},{"label":"C","content":"another"},{"label":"D","content":"a lot"}],"answer":"A","explanation":"空格后是名词复数，这是一个很明显的提示。能和名词复数搭配的就是 A 选项。less 和不可数名词搭配；another 用在单数棵树名词之前；a lot 是副词，不能修饰名词，但 a lot of  既可修饰可数名词复数，又可修饰不可数名词。","no":19},{"id":"1718789648927","type":"single","material":"","stem":"Although the airline has cut the number of cities（）it flies to, each week several flights still make the round trip from Cuba to Jamaica.","options":[{"label":"A","content":"where"},{"label":"B","content":"when"},{"label":"C","content":"that"},{"label":"D","content":"what"}],"answer":"C","explanation":"空格后的句子（it flies to）是不完整的，因此可排除关系副词。在 what 和 that 之中，应当选择能够修饰先行词的 关系代词 that（在从句中是宾语）。","no":20},{"id":"1718789648928","type":"single","material":"","stem":"It is well known that employees do not contribute enough（）the plans.","options":[{"label":"A","content":"from"},{"label":"B","content":"to"},{"label":"C","content":"with"},{"label":"D","content":"at"}],"answer":"B","explanation":"4 个选项都是介词。如果不能从后面的名词来判断答案，那么就要考虑不是和前面的动词构成固定搭配了。 contribute A to B 向 B 提供 A。记住“contribute to+名词”也能以不及物动词的形式使用。","no":21},{"id":"1718789648929","type":"single","material":"","stem":"The company plans to（）and reorganize many of its stores to eliminate overlap in jobs and office functions.","options":[{"label":"A","content":"closely"},{"label":"B","content":"close"},{"label":"C","content":"closed"},{"label":"D","content":"be closed"}],"answer":"B","explanation":"plan 在这里是以 to 不定式为宾语的及物动词。B 选项和 D 选项为动词原形，因此可能是正确答案。接下来，句子 中有明确的宾语，这是解题的关键。当剧中两个动词以 and 链接时，and 后面的动词（reorganize）如果宾语，则动词 是主动语态，否则就是被动语态。","no":22},{"id":"1718789648930","type":"single","material":"","stem":"<p>Mr. Kelly has the same question（ &nbsp; ）the warehouse locaition which we intend to use. </p>","options":[{"label":"A","content":"concerning"},{"label":"B","content":"regards"},{"label":"C","content":"with respect"},{"label":"D","content":"as of"}],"answer":"A","explanation":"空格前面的部分是个完整的句子， 因此空格内应填入使后面的名词变成修饰语的介词。有此功能的介词是 A 选项 和 D 选项，其中A 选项在意义上更为符合。","no":23},{"id":"1718789648931","type":"single","material":"","stem":"Two months ago, we were very bearish, but（）then we have switched our strategy to the bullish side.","options":[{"label":"A","content":"yet"},{"label":"B","content":"still"},{"label":"C","content":"already"},{"label":"D","content":"since"}],"answer":"D","explanation":"这里的 then 是名词，它的前面应该填入介词。选项中只有 D 选项是介词，其他选项都是副词。","no":24},{"id":"1718789648932","type":"single","material":"","stem":"<p>The executives have repeatedly indicated the company's interest in setting up shops provided the regulatory（ &nbsp; ）are removed.</p>","options":[{"label":"A","content":"provides"},{"label":"B","content":"hurdles"},{"label":"C","content":"handles"},{"label":"D","content":"paddles"}],"answer":"B","explanation":"空格内应填入名词，所以排除 A 选项。剩下的选项通过释义来判断，remove a hurdle 意为“移除障碍物”。","no":25},{"id":"1718789648933","type":"single","material":"","stem":"More than 300, 00 Koreans have a net worth over $1 million, （）property.","options":[{"label":"A","content":"excluding"},{"label":"B","content":"exclude"},{"label":"C","content":"to exclude"},{"label":"D","content":"excluded"}],"answer":"A","explanation":"空格前的部分是一个完整的句子，因此空格内应填入介词，与 property 构成句子的状语成分。excluding在做介词时意 为“除...之外”。","no":26},{"id":"1718789648934","type":"single","material":"","stem":"We are supposed to discuss what an increasing number of people consinder to be an（）dangerous product.","options":[{"label":"A","content":"inherently"},{"label":"B","content":"inherent"},{"label":"C","content":"inherency"},{"label":"D","content":"inherence"}],"answer":"A","explanation":"空格内应填入修饰形容词（dangerous）的副词。inheretly dangerous 意为“生性危险的”。然而，在“冠词+副词 （空格）+形容词+名词”的形式中，需要留意空格内填入的词语究竟是修饰形容词的副词，还是修饰名词的形容词。","no":27},{"id":"1718789648935","type":"single","material":"","stem":"The employee who worked most of his life in this division（）\"Employee of the Year\".","options":[{"label":"A","content":"has been awarded"},{"label":"B","content":"awarded"},{"label":"C","content":"have awarded"},{"label":"D","content":"is awarded"}],"answer":"A","explanation":"所有的选项都是谓语动词。考虑到单复数的问题，排除 C 选项。接下来考虑主动语态还是被动语态，award 是和 give 同类的及物动词，因此后面应跟一个直接宾语和一个间接宾语。如果只有一个宾语，那么就是被<br>动语态的用法。最后考虑时态，句子里说的是颁奖给“一直”为某事努力的人，所以应该使用现在完成时。","no":28},{"id":"1718789648936","type":"single","material":"","stem":"The interviewing process we use is（）just a skills assessment, but something called behavior-based interviewing.","options":[{"label":"A","content":"nor"},{"label":"B","content":"not"},{"label":"C","content":"as"},{"label":"D","content":"yet"}],"answer":"B","explanation":"not only(=just)A but (also)B 是一个句型，意为“不仅 A...而且 B 也... ”。","no":29},{"id":"1718789648937","type":"single","material":"","stem":"<p>The president was （ ） for a consultant to devise a new business plan.</p><p><br></p>","options":[{"label":"A","content":"arranging"},{"label":"B","content":"mentioning"},{"label":"C","content":"referring"},{"label":"D","content":"looking"}],"answer":"D","explanation":"<p>选项 A：“arrange for” 意为 “安排”，但 “安排顾问” 语义不符（题干是 “寻找顾问”）。<p>选项 B：“mention” 意为 “提及”，无 “mention for” 的合理搭配，语义不通。<p>选项 C：“refer” 常与 “to” 搭配（“refer to” 意为 “参考、涉及”），“refer for” 搭配错误。<p>选项 D：“look for” 是 “寻找” 的固定搭配，符合 “总裁寻找顾问设计商业计划” 的语境。","no":30},{"id":"1718789648938","type":"single","material":"","stem":"<p>（ &nbsp;）persons in the manufacturing industry <span>need more training to improve their skills.</span></p>","options":[{"label":"A","content":"Ongoing"},{"label":"B","content":"Inexperienced"},{"label":"C","content":"Upcoming"},{"label":"D","content":"Informing"}],"answer":"B","explanation":"本题考查形容词的用法。inexperienced persons 意为“没有经验的人们”","no":31},{"id":"1718789648939","type":"single","material":"","stem":"As soon as we（）the new assembly plant, our production capacity will almost double or even triple.","options":[{"label":"A","content":"are completed"},{"label":"B","content":"completing"},{"label":"C","content":"will complete"},{"label":"D","content":"complete"}],"answer":"D","explanation":"空格处应填入谓语动词，并且是主动语态。根据句首的 as soon as 来考虑时态由于它是引导时间状语从句的连词 , 所以不恩能够用将来时，只能用现在时。","no":32},{"id":"1718789648940","type":"single","material":"","stem":"Passengers must notify airline crews in advance when carrying baggage in excess of the maximum weight（）of 60lbs.","options":[{"label":"A","content":"approval"},{"label":"B","content":"allowance"},{"label":"C","content":"consent"},{"label":"D","content":"decisively"}],"answer":"B","explanation":"以复合名词为突破口就能轻松解题。maximum weight allowance 意为“伟大承重许可”","no":33},{"id":"1718789648941","type":"single","material":"","stem":"<p>The consulting firm _____ China as the seventh largest retail market in the world, behind the United States, Japan, the United Kingdom, Germany, France and Italy.</p>","options":[{"label":"A","content":"ranks"},{"label":"B","content":"thinks"},{"label":"C","content":"tells"},{"label":"D","content":"speaks"}],"answer":"A","explanation":"遇到考查动词用法的题目，就要注意空格后面的部分。rank A as B，意为“把 A 评为 B 级”。所有选项中的动词都 很重要，请一定通过查字典、看例句来掌握它们的用法。","no":34},{"id":"1718789648942","type":"single","material":"","stem":"Mr. Yun will supply you with the（）information required to register your product at the appliances exposition.","options":[{"label":"A","content":"specific"},{"label":"B","content":"specified"},{"label":"C","content":"specifying"},{"label":"D","content":"specify"}],"answer":"A","explanation":"空格内应填入起形容词作用的单词,因而就要通过分辨A项、B项、C项这3个选项意义上的差别来解题。一个秘诀是,当很难从语感上判断时,就选择原始的形容词。specific information 意为“具体信息”。","no":35},{"id":"1718789648943","type":"single","material":"","stem":"Our consumers are very（）to quality and freshness of food.","options":[{"label":"A","content":"used"},{"label":"B","content":"contributed"},{"label":"C","content":"attributed"},{"label":"D","content":"sensitive"}],"answer":"D","explanation":"这里仍然是“be+形容词+介词”的句式。be sensitive to sth.意为“对某事敏感”。","no":36},{"id":"1718789648944","type":"single","material":"","stem":"When you have（）time, you'll spend it more wisely.","options":[{"label":"A","content":"little"},{"label":"B","content":"lesser"},{"label":"C","content":"lessen"},{"label":"D","content":"less"}],"answer":"D","explanation":"空格内应填入形容词。lesser 是形容词，但意义上不符， 因此排除。在 little 和 less 之中，从句意上来说这里应当 选择比较级。","no":37},{"id":"1718789648945","type":"single","material":"","stem":"No date has been（）for a unified business tax rate.","options":[{"label":"A","content":"dealt"},{"label":"B","content":"notified"},{"label":"C","content":"set"},{"label":"D","content":"allowed"}],"answer":"C","explanation":"在考查被动语态的题目中，要注意主语。这里主语实际上是宾语。","no":38},{"id":"1718789648946","type":"single","material":"","stem":"Whether Thomas will close the deal still remains（）.","options":[{"label":"A","content":"see"},{"label":"B","content":"to seen"},{"label":"C","content":"to be seen"},{"label":"D","content":"seeing"}],"answer":"C","explanation":"“remain(to be)+形容词/名词”是一个句式，并且后面接形容词的形式更常见。remain to be seen 意为“有待考虑 ”, 最好记住。有时 to be 被省略，直接跟过去分词，起形容词的作用，做remain 的表语。记住这一点，回答其他题目 也可得心应手。","no":39},{"id":"1718789648947","type":"single","material":"","stem":"By next year it（）necessary to double the production quota to keep up with market demands.","options":[{"label":"A","content":"were"},{"label":"B","content":"will be"},{"label":"C","content":"has been"},{"label":"D","content":"being"}],"answer":"B","explanation":"空格内应填入单数形式的谓语动词。这里不需要分辨主动语态和被动语态，只要考虑时态。时态在大部分情况下 都是解题的提示。看到有 next year，这是不是一个有力的提示？","no":40},{"id":"1718789648948","type":"single","material":"","stem":"At the time this session ends, all the attendees should follow the signs（）the exits on the right side of the conference room.","options":[{"label":"A","content":"of"},{"label":"B","content":"to"},{"label":"C","content":"through"},{"label":"D","content":"for"}],"answer":"B","explanation":"follow the signs 意为“根据指示牌”。啊哈！地点的转移！表示地点转移的介词是B项、C项和D选项。意思是让大家根 据指示牌到达出口，因此正确答案应为表示“到达（某处）”的to。through意为“通过，穿过”。","no":41},{"id":"1718789648949","type":"single","material":"","stem":"When customer service representatives speak to customers over the phone, they should always speak（）.","options":[{"label":"A","content":"hardly"},{"label":"B","content":"clearly"},{"label":"C","content":"respectably"},{"label":"D","content":"respectively"}],"answer":"B","explanation":"遇到副词，要考虑它和动词的搭配。speak clearly 意为“说得很明确”。hardly 用在 be 动词和助动词的后面、一 般动词的前面，所以出现在 speak 的前面才对。respectably 意为“可敬地”如果是 respectfully 则可以被选。","no":42},{"id":"1718789648950","type":"single","material":"","stem":"The familiarity factor is so important that two-thirds of the companies he invests in（）in the neighboring area.","options":[{"label":"A","content":"locating"},{"label":"B","content":"being"},{"label":"C","content":"located"},{"label":"D","content":"are located"}],"answer":"D","explanation":"本题的句子分析非常重要，空格内应填入谓语动词。主语是“三分之二的公司”，he invests in 是关系代词引导的 定语从句。因此，排除 A 选项和 B 选项。locate 是及物动词，但是后面没有宾语，所以应填入被动语态。","no":43},{"id":"1718789648951","type":"single","material":"","stem":"<p>The（ &nbsp; ）information concerning this project will be provided for your convenience.</p>","options":[{"label":"A","content":"specification"},{"label":"B","content":"specifically"},{"label":"C","content":"specific"},{"label":"D","content":"Specify"}],"answer":"C","explanation":"空格内 应填入形容词，因为是在冠词和名词之间。在这样的结构中，空格里往往应填入形容词。","no":44},{"id":"1718789648952","type":"single","material":"","stem":"We can discuss it with the manager, （）not with the customer himself.","options":[{"label":"A","content":"while"},{"label":"B","content":"and"},{"label":"C","content":"after"},{"label":"D","content":"yet"}],"answer":"D","explanation":"and 和 yet(=but)都是连接平行成分的连词。空格前后都各有一个“with+名词”（介词+名词），这就是解题的关键。第二个 with 的前面省略了 we can discuss it，因此在 and 和 yet 之中应当选择含有 but 之意的 yet。还记 得 not A but B 这一固定用法吗？把它的形式换一下，就成了 B but not A。这道题把 but 换成了 yet ，难度非常大。","no":45},{"id":"1718789648953","type":"single","material":"","stem":"Prospective employees must have a master's degree to be eligible（）the positions described below.","options":[{"label":"A","content":"to"},{"label":"B","content":"for"},{"label":"C","content":"despite"},{"label":"D","content":"about"}],"answer":"B","explanation":"把“be+形容词+介词”当作固定用法来记忆。“be eligible for+名词/to do”意为“有资格做某事”。A 选项是个陷阱 , 性急的人可能会上当。注意，空格后面的部分并不是动词原形。","no":46},{"id":"1718789648954","type":"single","material":"","stem":"If our budget for office supplies（）, all new requests for them will have to be approved a case-by-case basis.","options":[{"label":"A","content":"is exhausting"},{"label":"B","content":"are exhausting"},{"label":"C","content":"is exhausted"},{"label":"D","content":"will be exhausted"}],"answer":"C","explanation":"空格内应填入动词的单数形式。以 ex-开头的动词是及物动词。没有宾语则应使用被动语态，也就是选择 C 或 D 选项。最后，要掌握时间、条件状语从句的用法。","no":47},{"id":"1718789648955","type":"single","material":"","stem":"The company is likely to be prosecuted because it has dumped environmentally hazardous materials（）.","options":[{"label":"A","content":"illegal"},{"label":"B","content":"illegally"},{"label":"C","content":"illegality"},{"label":"D","content":"illegalizing"}],"answer":"B","explanation":"当空格前是个完整句子时，空格内应填入副词。句子结构的分析是最基本的。这不仅仅是为了托业考试，而是为 了学习英语整个过程。笔者就是以此攻克了英语写作以及会话的。希望大家也一起来实践。","no":48},{"id":"1718789648956","type":"single","material":"","stem":"<p>The second shipment of ink cartridges was（）due to some defects in the quality. </p>","options":[{"label":"A","content":"contaminated"},{"label":"B","content":"refused"},{"label":"C","content":"deteriorated"},{"label":"D","content":"incurred"}],"answer":"B","explanation":"后面的 defect 是解题的提示。货品有缺陷，怎么做才好呢？当然是拒收了。","no":49},{"id":"1718789648957","type":"single","material":"","stem":"The directors that participated in the meeting were required to contribute（）suggestions to their colleagues.","options":[{"label":"A","content":"theirs"},{"label":"B","content":"their"},{"label":"C","content":"them"},{"label":"D","content":"themselves"}],"answer":"B","explanation":"本题空格在名词的前面，4 个选项中只有所有格可以填入。所有格的作用相当于形容词，可以用在名词前面，但不 能用在代词前面，否则就重复了。","no":50},{"id":"1718789648958","type":"single","material":"","stem":"This herbal medication native to Korea is（）to millions of people worldwide annually.","options":[{"label":"A","content":"overseen"},{"label":"B","content":"arranged"},{"label":"C","content":"prescribed"},{"label":"D","content":"selected"}],"answer":"C","explanation":"这一句用了被动语态，所以主语实际上是宾语。prescribe medication to sb.意为“为某人开药”。","no":51},{"id":"1718789648959","type":"single","material":"","stem":"He must submit a concrete cnergy（）that is to be carried out soon.","options":[{"label":"A","content":"plan"},{"label":"B","content":"planning"},{"label":"C","content":"plans"},{"label":"D","content":"planned"}],"answer":"A","explanation":"看到复合名词， 同时后面有 that is,就必须能够迅速判断填入答案的单复数。这样的题，意外做错的情况不少。","no":52},{"id":"1718789648960","type":"single","material":"","stem":"The board of directors（）has had different views on the current economy.","options":[{"label":"A","content":"strong"},{"label":"B","content":"stronger"},{"label":"C","content":"strongest"},{"label":"D","content":"strongly"}],"answer":"D","explanation":"主语和动词之间不应填入形容词，而应填入副词。除了 D 选项以外没有副词。把正确答案为副词的题目集合起来 整理复习吧。这样的题目要是做错了，那可真遗憾了。","no":53},{"id":"1718789648961","type":"single","material":"","stem":"The manager did not（）any differences between us.","options":[{"label":"A","content":"notice"},{"label":"B","content":"convene"},{"label":"C","content":"notify"},{"label":"D","content":"indicate"}],"answer":"A","explanation":"notice the difference 意为“注意到差别”。convene 做“聚集”解时是不及物动词，因此没有宾语；notify 是“通 知”的意思，后面应该接表示人的词语（notify sb of sth;notify sb that...）","no":54},{"id":"1718789648962","type":"single","material":"","stem":"Nowadays, we do almost all our（）by e-mail for business purposes.","options":[{"label":"A","content":"connection"},{"label":"B","content":"correspondence"},{"label":"C","content":"contract"},{"label":"D","content":"construction"}],"answer":"B","explanation":"解题时要注意找到提示点。by e-mail 就是本题的提示。能用电子邮件做的事就是通讯。","no":55},{"id":"1718789648963","type":"single","material":"","stem":"The company（）to lose one of its oldset accounts since it failed to meet the customer's needs several times.","options":[{"label":"A","content":"expects"},{"label":"B","content":"relies"},{"label":"C","content":"acquires"},{"label":"D","content":"negotiates"}],"answer":"A","explanation":"这里考查的是 to 不定式的用法。expect to do 意为“期待做某事”。","no":56},{"id":"1718789648964","type":"single","material":"","stem":"<p><span>It is essential that everyone （ ） safety procedures in the event of an emergency.</span></p>","options":[{"label":"A","content":"follow"},{"label":"B","content":"followed"},{"label":"C","content":"following"},{"label":"D","content":"be followed"}],"answer":"A","explanation":"<p>选项 A：“follow” 为动词原形，符合 “(should) follow” 的虚拟语气结构，且 “everyone” 与 “follow” 是主动关系，语法和语义均正确。<p>选项 B：“followed” 是过去式，不符合虚拟语气要求。<p>选项 C：“following” 是现在分词，不能作谓语。<p>选项 D：“be followed” 是被动语态，而 “everyone” 与 “follow” 是主动关系，逻辑不符。","no":57},{"id":"1718789648965","type":"single","material":"","stem":"Our redesigned business-class cabin is the obvious anwer（）your request for more space.","options":[{"label":"A","content":"for"},{"label":"B","content":"to"},{"label":"C","content":"at"},{"label":"D","content":"upon"}],"answer":"B","explanation":"对于要求事项的回答是从某一方到另一方，因此最合适的选择是表示移动与到达的 to。作为参考，answer 做及物 动词时后面不能加 to.只有做名词的时候后面才可以加 to。","no":58},{"id":"1718789648966","type":"single","material":"","stem":"Customer's demands have outpaced the business sector's ability（）such growing expectations.","options":[{"label":"A","content":"meeting"},{"label":"B","content":"to meeting"},{"label":"C","content":"to meet"},{"label":"D","content":"for meeting"}],"answer":"C","explanation":"这里的 to 不定式用来表示将来的事情。ability to do 意为“做某事的能力”（请记得 be able to do）。作为参考，请 记住后面带 to 不定式的名词（right,effort,chance,attempt,way 等）。","no":59},{"id":"1718789648967","type":"single","material":"","stem":"The committee will continue to look into the data（）to determine if the marketing survey can be a better guide for the labor market.","options":[{"label":"A","content":"informatively"},{"label":"B","content":"strictly"},{"label":"C","content":"narrowly"},{"label":"D","content":"closely"}],"answer":"D","explanation":"副词必须注意与它修饰的动词的搭配。look into the data closely 意为“深入研究资料”。","no":60},{"id":"1718789648968","type":"single","material":"","stem":"Hes said some（）had been made last month in talks on early retirement.","options":[{"label":"A","content":"pressentiaton"},{"label":"B","content":"procedure"},{"label":"C","content":"progress"},{"label":"D","content":"potential"}],"answer":"C","explanation":"make 在这里是被动语态的形式， 因此 C 选项实际上在句中充当宾语。make progress 意为“取得进展”。请记住“ make(A. +名词”这个表达形式。","no":61},{"id":"1718789648969","type":"single","material":"","stem":"The labor union remained open to dialgue and was（）to take measures to resolve the conflicts.","options":[{"label":"A","content":"ready"},{"label":"B","content":"complete"},{"label":"C","content":"organized"},{"label":"D","content":"inclusive"}],"answer":"A","explanation":"本题考查“be+形容词+to do”这一表达形式。be ready to do 意为“愿意、准备好做某事”。","no":62},{"id":"1718789648970","type":"single","material":"","stem":"It was a request from the speaker that the audience（）quiet.","options":[{"label":"A","content":"would be"},{"label":"B","content":"was"},{"label":"C","content":"been"},{"label":"D","content":"be"}],"answer":"D","explanation":"a request 是解题的关键。这里要表达的是一个“应该做某事”的请求，省略了should， 因此应该用动词原形。凡 是主张、命令、提案、忠告都应该选择这一用法。","no":63},{"id":"1718789648971","type":"single","material":"","stem":"The singularly（）restaurant is usually crowded with patrons.","options":[{"label":"A","content":"acquainted"},{"label":"B","content":"solicited"},{"label":"C","content":"diverse"},{"label":"D","content":"popular"}],"answer":"D","explanation":"常有回头客的餐馆是“受欢迎的”餐馆。","no":64},{"id":"1718789648972","type":"single","material":"","stem":"Eurpean carmakers will expand their business in Asia, relying on local manufacturers to develop new models（）their brand names.","options":[{"label":"A","content":"to bear"},{"label":"B","content":"bearing"},{"label":"C","content":"born"},{"label":"D","content":"bore"}],"answer":"B","explanation":"空格内应填入分谓语动词，所以排除 D 选项。又由于空格是在名词和名词中间，所以应填入现在分词（-ing）。在 这种结构中，前一个名词是动作的主体，中间动词是动作，后一个名词是动作的宾语。请记住这种表达形式（分词的 要领）。","no":65},{"id":"1718789648973","type":"single","material":"","stem":"In a survey, many U. S. managers（）about the bad quality of offshore work and unexpected costs.","options":[{"label":"A","content":"arrange"},{"label":"B","content":"disclose"},{"label":"C","content":"complain"},{"label":"D","content":"prepare"}],"answer":"C","explanation":"空格后有介词，所以应排除及物动词 A 选项和 B 选项。在剩下的选项中，能和 about 搭配的是 C选项。 complain about 意为“抱怨某事”，offshore 意为“国外的”。","no":66},{"id":"1718789648974","type":"single","material":"","stem":"Notify your supervisor of the days you would like to take off, （）approval.","options":[{"label":"A","content":"requests"},{"label":"B","content":"requseted"},{"label":"C","content":"requesting"},{"label":"D","content":"request"}],"answer":"C","explanation":"空格内应填入非谓语动词。因此，在 B 选项和 C 选项中选择，后接宾语、主动语态形式的 C 选项是正确答案。","no":67},{"id":"1718789648975","type":"single","material":"","stem":"The manufacturer lost many of its most loyal customers after the media focused attention on its lack of（）to product quality.","options":[{"label":"A","content":"commitment"},{"label":"B","content":"assurance"},{"label":"C","content":"value"},{"label":"D","content":"interest"}],"answer":"A","explanation":"本题应靠释义来解题，但空格后的 to 也解题的提示。commitment to 意为“保证/献身于某事”，当名词或动词后 面有介词时，要注意习惯搭配。","no":68},{"id":"1718789648976","type":"single","material":"","stem":"This restructuring（）to save the company more than 3 million dollars per year.","options":[{"label":"A","content":"expects"},{"label":"B","content":"are expected"},{"label":"C","content":"expected"},{"label":"D","content":"is expected"}],"answer":"D","explanation":"空格内应填入动词的单数被动形式。当 expect 的主语是事物时，只能用被动语态；而主语是人时，主动语态和被 动语态都可以使用。","no":69},{"id":"1718789648977","type":"single","material":"","stem":"I bet he is well（）for the position of taking care of his staff.","options":[{"label":"A","content":"engaged"},{"label":"B","content":"successful"},{"label":"C","content":"qualified"},{"label":"D","content":"reserved"}],"answer":"C","explanation":"be(well) qualified for 意为“（很）具有做某事的资格”","no":70},{"id":"1718789648978","type":"single","material":"","stem":"Presently, （）appears that the problem of absenteeism has yet to be adequately addressed.","options":[{"label":"A","content":"he"},{"label":"B","content":"its"},{"label":"C","content":"his"},{"label":"D","content":"it"}],"answer":"D","explanation":"应在能做主语的 he 和 it 之中选择答案。后面有 that，所以应选形式主语 it 。it appears that...意为<br>“好像... ”。","no":71},{"id":"1718789648979","type":"single","material":"","stem":"<p>The loan agency granted a 3 week（ &nbsp; ）on the loan of $100, 100 at the request of Mr. Cha.</p>","options":[{"label":"A","content":"exhaustion"},{"label":"B","content":"extension"},{"label":"C","content":"explanation"},{"label":"D","content":"execution"}],"answer":"B","explanation":"对于贷款，进行了 3 周的什么？grant an extension 意为“批准延期”。","no":72},{"id":"1718789648980","type":"single","material":"","stem":"His experience with Gates taught（）to think big and to never miss an opportunity to learn something new.","options":[{"label":"A","content":"his"},{"label":"B","content":"himself"},{"label":"C","content":"he"},{"label":"D","content":"him"}],"answer":"D","explanation":"空格内应填入及物动词 teach 的宾语，所以宾语的 him 是正确答案。himself 只有在动作主体与对象是用一个人 时才能使用。","no":73},{"id":"1718789648981","type":"single","material":"","stem":"Find a user group in your area and attend a meeting to learn how to use our products more（）.","options":[{"label":"A","content":"effectively"},{"label":"B","content":"profusely"},{"label":"C","content":"increasingly"},{"label":"D","content":"fluently"}],"answer":"A","explanation":"遇到副词，要考虑它和最近动词的搭配。use our products effcetively 意为“有效率地使用我们的产品”。","no":74},{"id":"1718789648982","type":"single","material":"","stem":"What a/an（）it is to be part of this very stimulating conference.","options":[{"label":"A","content":"anticipation"},{"label":"B","content":"admiration"},{"label":"C","content":"honor"},{"label":"D","content":"humiliation"}],"answer":"C","explanation":"what an honor it is to do 意为“做某事感到十分光荣”。","no":75},{"id":"1718789648983","type":"single","material":"","stem":"The list is based on a survey of 10, 000 corporate directors, executives, and analysts at（）350 companies.","options":[{"label":"A","content":"more than"},{"label":"B","content":"increasingly"},{"label":"C","content":"exceptionally"},{"label":"D","content":"until"}],"answer":"A","explanation":"请记住常出现在数字前面的词。“more than/less than+数字”意为“... 以上/以下”。“大约”也是经常出现（roughly ,approximately,nearly,almost,about,around 等）。","no":76},{"id":"1718789648984","type":"single","material":"","stem":"They have succeeded not just because market conditions favored their style（）because their investing discipline helped them.","options":[{"label":"A","content":"but"},{"label":"B","content":"only"},{"label":"C","content":"quite"},{"label":"D","content":"such"}],"answer":"A","explanation":"本题考察“not just...but...”结构的用法。前半句“not just because...”表示“不仅仅因为.……”，后半句需填入“but”构成“not just...but...”结构，表示“不仅…….而且.”其他选项如“only”、“quite”、“such”均不符合语法规则或语义连贯性。","no":77},{"id":"1718789648985","type":"single","material":"","stem":"The firm has seen considerable changes after he（）to be the director of the business division.","options":[{"label":"A","content":"elect"},{"label":"B","content":"to elect"},{"label":"C","content":"was elected"},{"label":"D","content":"elected"}],"answer":"C","explanation":"空格内应填入谓语动词，并和 after(连词)后的主语和 he 搭配。首先排除 B 选项；因为应填入动词的单数形式， 排除 A 选项；C 选项和 D 选项则是主动语态和被动语态的区分。空格后没有可以做宾语的名词，因此选择被动语态， 是 elect him(to be)the director 的被动形式。","no":78},{"id":"1718789648986","type":"single","material":"","stem":"LAPD reported that the middle-aged man had been apprehended at the scene（）after the accident.","options":[{"label":"A","content":"shortly"},{"label":"B","content":"rightly"},{"label":"C","content":"presently"},{"label":"D","content":"likely"}],"answer":"A","explanation":"空格内应填入修饰后面“介词+名词”的副词。4 个选项都是副词（likely 可以是形容词或副词）， 因此都有可能正 确答案。如果知道 shortly after(刚...之后)这个高频短语，那么便可轻松解题。当然，把 after 换成 before，就变成了“刚...之前”的意思。","no":79},{"id":"1718789648987","type":"single","material":"","stem":"The revised requirements will（）affect most of the new applicants.","options":[{"label":"A","content":"adversely"},{"label":"B","content":"adverse"},{"label":"C","content":"adverseness"},{"label":"D","content":"adversity"}],"answer":"A","explanation":"助动词和动词原形之间应当填入副词。因此 A 选项是正确答案。","no":80},{"id":"1718789648988","type":"single","material":"","stem":"Residents in this area requested to submit（）of residence to verify they actually live here.","options":[{"label":"A","content":"report"},{"label":"B","content":"request"},{"label":"C","content":"proof"},{"label":"D","content":"approval"}],"answer":"C","explanation":"本题考查名词的用法。解题的提示在于 to verify 这个地方，意为“证明他们实际在此居住过”。因此，为了证明 本人的居住事实，应该提交居住证明，也就是 proof of residence。","no":81},{"id":"1718789648989","type":"single","material":"","stem":"The Human Resources department is considering（）a new benefits package for the benefit of the employees.","options":[{"label":"A","content":"introduced"},{"label":"B","content":"to introduce"},{"label":"C","content":"being introduced"},{"label":"D","content":"introducing"}],"answer":"D","explanation":"consider 是以动名词为宾语的及物动词。空格后面还有宾语（a new benefits package 意为“新的福利制度”），因 此，在 C 选项和 D 选项中选择主动语态的 D 选项。不论是 to 不定式还是动名词，从原始动词出发，出现主动语态或被 动语态、有没有宾语都是有可能的。","no":82},{"id":"1718789648990","type":"single","material":"","stem":"The newly purchased equipment from Korea is capable（）and producing subminiature products.","options":[{"label":"A","content":"measuring"},{"label":"B","content":"to measure"},{"label":"C","content":"in measuring"},{"label":"D","content":"of measuring"}],"answer":"D","explanation":"请记住 be capable of sth。意为“有能力做某事”。不可与疑似相近的词组 be able to do 相混淆。","no":83},{"id":"1718789648991","type":"single","material":"","stem":"<p>（ &nbsp; ）the company is not as successful as other big companies, it's proven that it can expand internationally.</p>","options":[{"label":"A","content":"Even though"},{"label":"B","content":"If"},{"label":"C","content":"Yet"},{"label":"D","content":"As though"}],"answer":"A","explanation":"空格内应填入引导状语从句的连词。yet 是连词，不用在句首（and,but,or 亦为如此）。剩下的选项都是引导状语 从句的连词，通过释义能选出最符合的答案。","no":84},{"id":"1718789648992","type":"single","material":"","stem":"It was my deepest regret that i failed to submit my report by the（）deadline.","options":[{"label":"A","content":"ready"},{"label":"B","content":"original"},{"label":"C","content":"considering"},{"label":"D","content":"hesitant"}],"answer":"B","explanation":"本题考查修饰“最后期限”（deadline）一词的形容词。original deadline 意为“原始的最后期限”，是经常使用的 短语。也请记住 extended deadline 这一短语，意为“推迟的最后期限”。","no":85},{"id":"1718789648993","type":"single","material":"","stem":"One of the trainees is（）complaining that she has to put in an excessive amount of overtime to finish the paperwork.","options":[{"label":"A","content":"yet"},{"label":"B","content":"ever"},{"label":"C","content":"since"},{"label":"D","content":"still"}],"answer":"D","explanation":"所有选项都是起副词的作用。A 选项和 B 选项主要用在否定句中；since 主要用于完成时；still 主要用于肯定句以 及现在进行时，意为“仍然（在做某事）”。因此，D 选项为正确答案。请在脑海中整理下用副词的用法。","no":86},{"id":"1718789648994","type":"single","material":"","stem":"All workers can take a day off as the installation of cutting-edge facilities at our factory is（）underway.","options":[{"label":"A","content":"directly"},{"label":"B","content":"extremely"},{"label":"C","content":"presently"},{"label":"D","content":"Enormously"}],"answer":"C","explanation":"使用副 词来修饰形容词时，要考虑两者的搭配。presently underway 意为“现在进行中”。","no":87},{"id":"1718789648995","type":"single","material":"","stem":"I consider Mr. Kim as the most talented photographer（）love of the photogragh inspired visitors.","options":[{"label":"A","content":"whatever"},{"label":"B","content":"who"},{"label":"C","content":"whoever"},{"label":"D","content":"whose"}],"answer":"D","explanation":"先行词是 photographer,love 在这里做名词，所以应选择起所有格做的 whose.","no":88},{"id":"1718789648996","type":"single","material":"","stem":"Staff remaining in the lounge should notify their immediate supervisors before（）to their work.","options":[{"label":"A","content":"returning"},{"label":"B","content":"returns"},{"label":"C","content":"returned"},{"label":"D","content":"to return"}],"answer":"A","explanation":"空格内应填入非谓语动词。由于 before 是连词，后面填入分词形式的 A 选项或 C 选项都有可能。这个分词用来修 饰主句中的主语 staff，而 staff 是 return to their work 的行为主体。因此主动语态的 A 选项是正确答案。","no":89},{"id":"1718789648997","type":"single","material":"","stem":"<p>I will（ &nbsp; ）him that no methods were found for solving the conflicts associated with the refund.</p>","options":[{"label":"A","content":"announce"},{"label":"B","content":"talk"},{"label":"C","content":"mention"},{"label":"D","content":"remind"}],"answer":"D","explanation":"看到空格 后的“him that... ”,就知道这是一个“动词+间接宾语+直接宾语”的句式。适合这个句式的只有 D 选项。经常出现在题 目中的类似动词还有：notify,assure,remind,tell,advise 等。","no":90},{"id":"1718789648998","type":"single","material":"","stem":"If you do not receive e-mail bank statements we send you monthly, we'll contact you（）instead.","options":[{"label":"A","content":"unanimously"},{"label":"B","content":"mainly"},{"label":"C","content":"cautiously"},{"label":"D","content":"directly"}],"answer":"D","explanation":"如果交易细目报告的电子邮件收不到，不就应该“直接”联系吗？","no":91},{"id":"1718789648999","type":"single","material":"","stem":"<p>Our respect for customers and the environment is at the heart of（）everything we do. &nbsp;</p>","options":[{"label":"A","content":"most"},{"label":"B","content":"almost"},{"label":"C","content":"mostly"},{"label":"D","content":"any"}],"answer":"B","explanation":"everything 是名词，因此很容易想到形容词去修饰；但实际上，它是形容词 every 和名词 thing 结合而成的，应当 以副词来修饰。所有选项都是副词，词义也很相近。此时必须记住 almost everything 这个常用词组。也请记住almost everyone。","no":92},{"id":"1718789649000","type":"single","material":"","stem":"Their first proposal wasn't as complete as（）even though theirs was considered better and more thorough.","options":[{"label":"A","content":"we"},{"label":"B","content":"us"},{"label":"C","content":"ours"},{"label":"D","content":"ourselves."}],"answer":"C","explanation":"从整体上考虑,应当填入具有“我们的提案”之意的代词。这样,句子意思才能完整。因此,把our proposal简化,填入ours。在as ... as ... 这样的句式中,只有分析好词义才能顺利解题。因为在同位语从句中,相对的单词会被省略。比如本题中,as our proposal(was complete)替换成 as ours。","no":93},{"id":"1718789649001","type":"single","material":"","stem":"Sicne the most（）candidate showed his potential, it was certain that he would be elected.","options":[{"label":"A","content":"uncoming"},{"label":"B","content":"probable"},{"label":"C","content":"concerning"},{"label":"D","content":"previous"}],"answer":"B","explanation":"什么单词能与“选举”搭配？the most probable candidate,意为“最有可能当选的候选人”。类似prospect, potential,promising 等也是常用词语。请记住 potential client（潜在的客户）这个词组。","no":94},{"id":"1718789649002","type":"single","material":"","stem":"Our research shows that the younger generation tends to spend more and（）less than seniors.","options":[{"label":"A","content":"saving"},{"label":"B","content":"saved"},{"label":"C","content":"save"},{"label":"D","content":"to be saved"}],"answer":"C","explanation":"当空格的前后有 and 或其他连接平行成分的连词时，就要从词义上考虑一下，空格究竟应该跟在前面还是后面。 本题中，空格内应填入跟在 tends to","no":95},{"id":"1718789649003","type":"single","material":"","stem":"The real estate the company（）was sold at a higher price than the original one.","options":[{"label":"A","content":"purchased"},{"label":"B","content":"was purchased"},{"label":"C","content":"to purchase"},{"label":"D","content":"purchasing"}],"answer":"A","explanation":"real estate 后面省略了关系代词 which。因此，空格部分属于定语从句的一部分，应填入谓语动词。接下来应该考 虑是主动语态还是被动语态，在 A 选项和 B 选项中挑选。一般来说，没有宾语的话就应当选择被动语态。但是当句子中 有充当宾语的关系代词 which 时，宾语仍然是存在的，只不过跑到了句子前面。因此这里应当选择主动语态。","no":96},{"id":"1718789649004","type":"single","material":"","stem":"People began to conserve energy（）largely to the hike in raw material prices last year.","options":[{"label":"A","content":"according"},{"label":"B","content":"attempt"},{"label":"C","content":"due"},{"label":"D","content":"need"}],"answer":"C","explanation":"所有选项都能与 to 搭配。但是从意义上来说，“due(largely)to sth ”.意为“主要因为某事”，最为合适。这里的 largely 也可以换成 mainly 。partly because of 意为“部分因为某事”。","no":97},{"id":"1718789649005","type":"single","material":"","stem":"（）a 2% revaluation of the country last year, the big jump came.","options":[{"label":"A","content":"In spite of"},{"label":"B","content":"Although"},{"label":"C","content":"However"},{"label":"D","content":"Nevertheless"}],"answer":"A","explanation":"空格内应填入一个介词，与空格后的名词搭配成为整个句子的修饰成分（介词+名词=修饰语）。起介词作用的只 有 A 选项。","no":98},{"id":"1718789649006","type":"single","material":"","stem":"I also find（）amusing that you have a pleasant studying English.","options":[{"label":"A","content":"those"},{"label":"B","content":"yourself"},{"label":"C","content":"it"},{"label":"D","content":"myself"}],"answer":"C","explanation":"find 主要做及物动词使用，因此空格后应填入宾语。看了选项之后，就会明白实际上宾语是 that引导的名词性从 句。","no":99},{"id":"1718789649007","type":"single","material":"","stem":"I could go on but I am too busy（）any more time to this.","options":[{"label":"A","content":"to donate"},{"label":"B","content":"donating"},{"label":"C","content":"donated"},{"label":"D","content":"donation"}],"answer":"A","explanation":"这里很容易被误以为是 be busy+ -ing 的结构。这里的“too+形容词/副词+to do”意为“过于（形容词/副词）... 而不能做某事”。不要拘泥于固定用法，做题时要从整体上来把握。实际上，高手们做题时并不是只看空格前后的部分。只有仔细分析每个选项，慎重解题，才能变成高手。","no":100},{"id":"1718789649008","type":"single","material":"","stem":"Even as a leader at home, it won't be easy for company to establish that same kind of（）in other areas.","options":[{"label":"A","content":"presumption"},{"label":"B","content":"dominance"},{"label":"C","content":"hospitality"},{"label":"D","content":"clearance"}],"answer":"B","explanation":"即使是在国内处于领先地位的企业，在其他地区什么一样的事情是不容易的呢？一样处于领先地位是不容易的。 能表达这个意思的选项 B 选项 dominance,意为“支配（地位），优势”。","no":101},{"id":"1718789649009","type":"single","material":"","stem":"When there's tension between the bank and the government over a policy, they have（）room for cooperation.","options":[{"label":"A","content":"little"},{"label":"B","content":"every"},{"label":"C","content":"another"},{"label":"D","content":"those"}],"answer":"A","explanation":"room 有“房间（可数），机会，空间（不可数）”的意思。在这里是“合作的机会”的意思，是不可数名词。选 项中与不可数名词搭配的只有 A 选项。","no":102},{"id":"1718789649010","type":"single","material":"","stem":"Many sales representatives prefer to use laptop computers because they are（）for people who travel a lot.","options":[{"label":"A","content":"convenience"},{"label":"B","content":"conveniently"},{"label":"C","content":"conveniences"},{"label":"D","content":"convenient"}],"answer":"D","explanation":"be/become/remain 这类动词经常跟形容词，做表语。这里的选项中只有 D 选项是形容词。如果以名词做表语， 必须和主语保持一致。","no":103},{"id":"1718789649011","type":"single","material":"","stem":"DHX provides（）to global marketplace information linking supply chains, transportations, and related information services.","options":[{"label":"A","content":"access"},{"label":"B","content":"accessible"},{"label":"C","content":"accessed"},{"label":"D","content":"accessing"}],"answer":"A","explanation":"provide 是及物动词，因此空格内应填入宾语。正确答案是名词 A 选项。provide access to 意为“使接近”","no":104},{"id":"1718789649012","type":"single","material":"","stem":"The manager, however, did not pay much attention（）the grounds that the problem will be solved soon.","options":[{"label":"A","content":"to"},{"label":"B","content":"from"},{"label":"C","content":"at"},{"label":"D","content":"on"}],"answer":"D","explanation":"on the ground(s) of/that...意为“根据..., 由于... ”，知道这个就能解题。因为是建立在根据之“上” 的行为，所以用 表示“在...上”的 on。","no":105},{"id":"1718789649013","type":"single","material":"","stem":"While it may sound（）, I think you will soon experience the improvement of your ability concentrating more on this lecture.","options":[{"label":"A","content":"indicative"},{"label":"B","content":"presumable"},{"label":"C","content":"interesting"},{"label":"D","content":"exaggerated"}],"answer":"D","explanation":"句子的大概意思是听话者的能力将得到提高。在这样的情况下， 常使用 while it may sound  exaggerated（“虽然这听起来可能有些夸张”）这一表示谦虚的说法。请将它多读几遍，直到熟记于心。","no":106},{"id":"1718789649014","type":"single","material":"","stem":"You are required to wear（）clothing before you cnter the room.","options":[{"label":"A","content":"protect"},{"label":"B","content":"protective"},{"label":"C","content":"protection"},{"label":"D","content":"protecting"}],"answer":"B","explanation":"及物动词 wear 和宾语 clothing 中间应当加入形容词做修饰语。这个时候，会有很多人以为 protection和 clothing 构 成复合名词而误选 C 选项。但重要的是，这个复合名词到底有没有为英语为母语的人在使用。Protection clothing 这个词是没有人用的。“保护用的... ”这一词组常写成“ protective ... ”（比如： protective eyewear,protective equipment 等）","no":107},{"id":"1718789649015","type":"single","material":"","stem":"Considering that the trade is growing rapidly, the surplus is（）to increase significantly in the coming year.","options":[{"label":"A","content":"reliably"},{"label":"B","content":"lovely"},{"label":"C","content":"newly"},{"label":"D","content":"likely"}],"answer":"D","explanation":"这里空格前面是 be，因此填入形容词是合适的。所有选项看起来都是副词，但 B 选项和 D 选项也有形容词的用 法。应选择符合句义的 D 选项。be likely to do 意为“有可能做某事”。","no":108},{"id":"1718789649016","type":"single","material":"","stem":"Hundreds of thousands of people gathered voluntarily in front of the Stadium（）the Semi-final day of 2006 World Cup.","options":[{"label":"A","content":"in"},{"label":"B","content":"on"},{"label":"C","content":"of"},{"label":"D","content":"at"}],"answer":"B","explanation":"“半决赛”是一个日期的概念，表示“在”哪一天的时候，用介词 on.","no":109},{"id":"1718789649017","type":"single","material":"","stem":"You will have to（）this reminder to all staff regarding changes in our unused vacation policy.","options":[{"label":"A","content":"distribute"},{"label":"B","content":"attribute"},{"label":"C","content":"contribute"},{"label":"D","content":"tribute"}],"answer":"A","explanation":"在考查动词用法的句子中，空格后面的宾语经常是解题的关键提示。拿着通知到职员们那里去做什么？就是“ 分发”，对吧。","no":110},{"id":"1718789649018","type":"single","material":"","stem":"We only collect, store and use your personal information for（）purposes throughout our businesses around the world.","options":[{"label":"A","content":"beneficial"},{"label":"B","content":"meaningful"},{"label":"C","content":"limited"},{"label":"D","content":"decisive"}],"answer":"C","explanation":"个人信息只能用于“限定性的”用途。因为个人信息是很宝贵的。","no":111},{"id":"1718789649019","type":"single","material":"","stem":"Among other things, we want to help you（）find information on the matters involved and notify you of product upgrades.","options":[{"label":"A","content":"quicken"},{"label":"B","content":"quick"},{"label":"C","content":"quickly"},{"label":"D","content":"quicker"}],"answer":"C","explanation":"help 常以“help+宾语+（to ）do”的形式使用（当然，也有“help+宾语”的形式）。本题中，help you find...具有前一种形式的全部要素。因此，空格应填入副词，做修饰成分。","no":112},{"id":"1718789649020","type":"single","material":"","stem":"<p>Periodically, we may send you information about our various products which we feel may be（）to you. </p>","options":[{"label":"A","content":"interest"},{"label":"B","content":"of interest"},{"label":"C","content":"interested"},{"label":"D","content":"interestingly"}],"answer":"B","explanation":"be 动词的后面接形容词，这一点已经很熟悉了，那么也要记住“介词+名词”也是相当于形容词的用法。 of interest 就相当于 interesting。","no":113},{"id":"1718789649021","type":"single","material":"","stem":"This presentation will show you examples of（）its solutions help companies operate more effectively.","options":[{"label":"A","content":"how"},{"label":"B","content":"however"},{"label":"C","content":"what"},{"label":"D","content":"where"}],"answer":"A","explanation":"本题中，介词（of）后应填入引导名词性从句（S+V)的连词。however 是引导状语从句的连词，因此排除。空 格后的句子是完整的，因此 what 也排除了。在how 和where 中，应选择更符合句义的 how.整理并记住各个连词引导 什么从句，分别有什么特性，是通向高分的必经之路。","no":114},{"id":"1718789649022","type":"single","material":"","stem":"（）products enable IT professionals to explore soon-to-be-released technologies.","options":[{"label":"A","content":"Less"},{"label":"B","content":"These"},{"label":"C","content":"Every"},{"label":"D","content":"Much"}],"answer":"B","explanation":"空格后的 products 是复数名词，因此与之搭配的是 these 。less 和 much 都只与不可数名词搭配；every 与单数可 数名词搭配。","no":115},{"id":"1718789649023","type":"single","material":"","stem":"Your（）effort is absolutely needed to find out what caused this accident.","options":[{"label":"A","content":"cooperatively"},{"label":"B","content":"cooperation"},{"label":"C","content":"cooperative"},{"label":"D","content":"cooperate"}],"answer":"C","explanation":"所有格和名词之间填入形容词。所有选项都是从同一单词派生而来，按顺序分别是副词、名词、形容词和动词。","no":116},{"id":"1718789649024","type":"single","material":"","stem":"We started to find（）managers who have excelled in a variety of market environments over a long period of time.","options":[{"label":"A","content":"missing"},{"label":"B","content":"opposing"},{"label":"C","content":"experienced"},{"label":"D","content":"significant"}],"answer":"C","explanation":"在很多领域从事过工作的经理，可以说是“经验丰富的”经理。","no":117},{"id":"1718789649025","type":"single","material":"","stem":"Several times of revisions will（）before a final product is produced for a competition.","options":[{"label":"A","content":"make"},{"label":"B","content":"be made"},{"label":"C","content":"makes"},{"label":"D","content":"made"}],"answer":"B","explanation":"空格谓语助动词的后面，因此应在动词原形的 A 选项或 B 选项中选择正确答案。make 是及物动词，后面没有宾 语的时候应使用被动语态。这里是把 make a revision（校订，修订）变成了被动语态。","no":118},{"id":"1718789649026","type":"single","material":"","stem":"A simple way to（）funds would be to offer an incentive program for the donors.","options":[{"label":"A","content":"generate"},{"label":"B","content":"manufacture"},{"label":"C","content":"deliver"},{"label":"D","content":"contract"}],"answer":"A","explanation":"本题考查动词的用法。请注意空格后面的宾语，资金要怎么样呢？请记住 generate funds 这一词组，意为“产生 资金”；manufacture 意为“制造”；deliver 意为“派送（物品）”,“传达（想法）”；contract 意为“订（约）”。","no":119},{"id":"1718789649027","type":"single","material":"","stem":"In case you pay any money in excess of the delivered package, it（）to your account later.","options":[{"label":"A","content":"is credited"},{"label":"B","content":"to be credited"},{"label":"C","content":"have been credited"},{"label":"D","content":"will be credited"}],"answer":"D","explanation":"这里主句中应使用将来时，所以 D 选项为正确答 案。","no":120},{"id":"1718789649028","type":"single","material":"","stem":"Due to Ms. Lin's presentation, we could（）our research into a few areas we had been neglecting before.","options":[{"label":"A","content":"allocate"},{"label":"B","content":"dilate"},{"label":"C","content":"impress"},{"label":"D","content":"broaden"}],"answer":"D","explanation":"本题仍然考查动词的用法。broaden A into B 意为“将A扩大为B”。","no":121},{"id":"1718789649029","type":"single","material":"","stem":"Firms are（）using independent consulting agencies to solve their problems.","options":[{"label":"A","content":"extremely"},{"label":"B","content":"increasingly"},{"label":"C","content":"highly"},{"label":"D","content":"consecutively"}],"answer":"B","explanation":"遇到副词，要注意它和动词的搭配。句子是说，有很多公司再越来越多地利用独立的咨询部门来处理问题，因 此应选择意为“越来越多地”的 increasingly。","no":122},{"id":"1718789649030","type":"single","material":"","stem":"It is said that the effective（）of personnel at all levels is a key to becoming an excellent manager.","options":[{"label":"A","content":"utilization"},{"label":"B","content":"utilizable"},{"label":"C","content":"utilize"},{"label":"D","content":"utilized"}],"answer":"A","explanation":"在“冠词+形容词+____ ”这个结构里，空格内应填入名词。虽然是非常简单的机构，但如果在送分题上丢分那 可真实可惜哦。","no":123},{"id":"1718789649031","type":"single","material":"","stem":"<p>As the recovery builds speed, it is likely to be sustained by a（）circle of forces.</p>","options":[{"label":"A","content":"vicious"},{"label":"B","content":"rotating"},{"label":"C","content":"virtuous"},{"label":"D","content":"spiral"}],"answer":"C","explanation":"对于经济方面的术语，还是有必要了解一些的。本题考查 vicious circle(恶性循环)个 virtuous circle(良性循环)是最恰 当的。","no":124},{"id":"1718789649032","type":"single","material":"","stem":"You can choose（）more than hundreds of information sessions and hands-on laboratory works.","options":[{"label":"A","content":"at"},{"label":"B","content":"through"},{"label":"C","content":"above"},{"label":"D","content":"from"}],"answer":"D","explanation":"句子表示这是一件可以从“数百以上的选项中挑选”的东西。from 表示“从... ”,是个介词。介词最好通过列表来记忆，请记住一系列与地点、场合搭配使用的介词。","no":125},{"id":"1718789649033","type":"single","material":"","stem":"We offer product demonstrations to all（）clients, as promised in our advertisements.","options":[{"label":"A","content":"prevented"},{"label":"B","content":"descriptive"},{"label":"C","content":"potential"},{"label":"D","content":"assured"}],"answer":"C","explanation":"产品的演示是对谁做的？这里自然应当将“潜在顾客”吸引过来变为实际顾客。与此类似， prospective,probable 也可以使用。","no":126},{"id":"1718789649034","type":"single","material":"","stem":"The Economy Survey subscription ha increased（）the marketing budget has been cut down.","options":[{"label":"A","content":"although"},{"label":"B","content":"because"},{"label":"C","content":"despite"},{"label":"D","content":"however"}],"answer":"A","explanation":"空格内应填入引导状语从句的连词。A 、B 和 D 选项中，词义上最恰当的是 A 选项。A 选项在考查引导状语从句 连词的题目中出题频率最高，其次是 because。也请记住“however+(形容词/副词+)S+V,S+V”（无论...都... ）这个句型，这对解题有一 定帮助。","no":127},{"id":"1718789649035","type":"single","material":"","stem":"Staff members within a firm are（）evaluated by their performance.","options":[{"label":"A","content":"admirably"},{"label":"B","content":"largely"},{"label":"C","content":"deeply"},{"label":"D","content":"previously"}],"answer":"B","explanation":"本题考查的是副词的用法。当遇到短句子的时候不要急着做，仔细看所有选项的意思反而能节省时间。句意是， 公司“主要”以业务成绩来评定职员。","no":128},{"id":"1718789649036","type":"single","material":"","stem":"Although he（）mentioned the introduction of that product, his remark still has a profound effect on his fellows.","options":[{"label":"A","content":"once"},{"label":"B","content":"besides"},{"label":"C","content":"still"},{"label":"D","content":"yet"}],"answer":"A","explanation":"空格内应填入副词。所有选项都可做副词使用，但词义上最合适，并且能和过去时搭配的只有 once 。once 当连词 用的时候是“一旦... ”的意思，引导条件状语从句。","no":129},{"id":"1718789649037","type":"single","material":"","stem":"Frequent customers should be reminded that extended business hours will remain in effect for the（）of the season.","options":[{"label":"A","content":"reminder"},{"label":"B","content":"remaining"},{"label":"C","content":"remain"},{"label":"D","content":"remainder"}],"answer":"D","explanation":"空格内应填入名词。remaining 是动名词，动名词一般前面不用冠词，后面也没有表语，所以排除。在 A 选项和 D 选项中，应当选择意为“剩下的部分”的 remainder.","no":130},{"id":"1718789649038","type":"single","material":"","stem":"Ms. Ann tried to bring the problem to a settlement by asking the manager sitting next to（）.","options":[{"label":"A","content":"herself"},{"label":"B","content":"himself"},{"label":"C","content":"him"},{"label":"D","content":"her"}],"answer":"D","explanation":"如果空格内填入反身代词，那么这个代词必须和动作的主体一致。这里填入的词语应该和 sitting的主体 manager  一致，如果 A 选项或 B 选项正确的话，就变成了“自己坐在自己边上”而这是不可能的。句中说道 manager坐在“Ms.的边上，因此 D 选项是正确答案。","no":131},{"id":"1718789649039","type":"single","material":"","stem":"DVDs are more common now than the VHS-type videotapes that were once so（）in watching movies at home.","options":[{"label":"A","content":"prevalent"},{"label":"B","content":"leading"},{"label":"C","content":"foremost"},{"label":"D","content":"habitual"}],"answer":"A","explanation":"句子的意思是：录像带曾经非常怎么样，而现在 DVD 很流行。那么当然是曾经很“普及的”意思。common 在这 里和 widespread 是同样的意思。","no":132},{"id":"1718789649040","type":"single","material":"","stem":"The rain check for sold-out opera tickets is valid（）on the date stamped on the ticket.","options":[{"label":"A","content":"only"},{"label":"B","content":"however"},{"label":"C","content":"also"},{"label":"D","content":"even"}],"answer":"A","explanation":"所有选项都是副词。句子是说，用于以后再买票的凭据，“只”在盖在票上的那个日期内有效。请牢记所有经常 出现在题目中的副词。","no":133},{"id":"1718789649041","type":"single","material":"","stem":"You may breach this agreement if you send copyrighted computer files（）.","options":[{"label":"A","content":"electrically"},{"label":"B","content":"electric"},{"label":"C","content":"electronic"},{"label":"D","content":"electronically"}],"answer":"D","explanation":"看到空格前面是 S+V+O 形式的完整句子，就该知道空格内应填入副词。A 选项和 D 选项在词义上很容易混淆。 但文件的传送不是“用电力”而是“用电子手段”，我们不是说“电子邮件”吗？","no":134},{"id":"1718789649042","type":"single","material":"","stem":"The lack of information concerning the bid should receive immediate attention, no matter（）she might have mentioned at the emergency meeting.","options":[{"label":"A","content":"whom"},{"label":"B","content":"when"},{"label":"C","content":"what"},{"label":"D","content":"how"}],"answer":"C","explanation":"no matter 的意思就和-ever 是一样的。换句话说，no matter whom 就相当于 whomever。于是这里就变成了复合 关系代词和复合关系副词。空格后面的 mention 是及物动词，但没有出现宾语，句子不完整，所以应在 whomever 和 whatever 之间选择；而句意是“不管她说什么”，指的是事物，所以whatever 是正确答案。","no":135},{"id":"1718789649043","type":"single","material":"","stem":"Besides a（）knowledge of business administration, candidates must have a minimum of 2 years experience for this project.","options":[{"label":"A","content":"open"},{"label":"B","content":"bright"},{"label":"C","content":"broad"},{"label":"D","content":"horizontal"}],"answer":"C","explanation":"句意是，除了“广泛地”了解商业管理的知识...就像我们平时说饿知识面“宽”或者“窄”的意思一样。","no":136},{"id":"1718789649044","type":"single","material":"","stem":"Most of the people know the importance of extensive research（）they fail to get accurate information at times.","options":[{"label":"A","content":"so"},{"label":"B","content":"either"},{"label":"C","content":"besides"},{"label":"D","content":"yet"}],"answer":"D","explanation":"4 个选项由连词和副词组成。这个时候就要赶紧看一下句子中共有几个 S+V 的结构？结果是两个。那么空格内当 然应该填入连词。从词义上来看，在 so 和 yet 之间应该选择 yet。作为参考，yet 有和 but 一样连接平行成分的连词用 法，也有 not yet（还没有）一样的副词用法。","no":137},{"id":"1718789649045","type":"single","material":"","stem":"The manager used to（）to each employee in person when something unexpected happened.","options":[{"label":"A","content":"say"},{"label":"B","content":"tell"},{"label":"C","content":"speak"},{"label":"D","content":"express"}],"answer":"C","explanation":"空格后介词 to ，那么空格内应填入的是不及物动词。在所有选择中，只有 speak 最合适。请记住speak/talk to/with sb.,speak/talk about sth.这些短语。剩下的选择都是及物动词，不能和介词搭配使用。况且，空格后也 没有宾语。及物动词和不及物动词的区分是基础中的基础。","no":138},{"id":"1718789649046","type":"single","material":"","stem":"The newly established restrictions prohibited the distributor from getting the goods cleared（）customs.","options":[{"label":"A","content":"through"},{"label":"B","content":"for"},{"label":"C","content":"on"},{"label":"D","content":"in"}],"answer":"A","explanation":"本题中，所有选项都是介词，那么就要从词义上来分析。句子中说到“货物过海关”，因此表示 “通过”的 through 是正确答案。","no":139},{"id":"1718789649047","type":"single","material":"","stem":"（）endangered species may not be protected from the hazards from human activities.","options":[{"label":"A","content":"Most the"},{"label":"B","content":"Most of"},{"label":"C","content":"Almost all of"},{"label":"D","content":"Almost all the"}],"answer":"D","explanation":"根据句义，空格这里应为“几乎所有的”这个意思。“most of the(或所有格)+名词=most of them=most+名词”，这个 时候 most 可以换成 almost all。或者说成“almost all the+名词”也可以。但是，并没有“most the+名词”这样的形式","no":140},{"id":"1718789649048","type":"single","material":"","stem":"（）under negotiation is a proposal to disallow pets in this apartment complex.","options":[{"label":"A","content":"Current"},{"label":"B","content":"Currently"},{"label":"C","content":"Currency"},{"label":"D","content":"Currents"}],"answer":"B","explanation":"能看出它是倒装句吗？这里主语是 a proposal,动词和表语是 is under negotiation“介词+名词”的结构也可以看 做是形容词的用法，所以这里可以的表语。由于句子不缺少成分，所以空格内应填入副词。","no":141},{"id":"1718789649049","type":"single","material":"","stem":"The assistant manager had to（）the manager while he was on a sick leave.","options":[{"label":"A","content":"get through"},{"label":"B","content":"take the place of"},{"label":"C","content":"put up with"},{"label":"D","content":"look for"}],"answer":"B","explanation":"当经理请病假时，经理助理要怎么做呢？当然是“代替（某职位）”, 也就是 take the place of。其余选项中的词 组，也请务必掌握。","no":142},{"id":"1718789649050","type":"single","material":"","stem":"The results from a survey（）that studying this book twice raises one's TOEIC score by almost 30%.","options":[{"label":"A","content":"refer"},{"label":"B","content":"inquire"},{"label":"C","content":"assure"},{"label":"D","content":"indicate"}],"answer":"D","explanation":"当要 that 引 导 的 从句来表示研究 、调查 、 新闻报道等的内容时，经常使用的动词有show,indicate,say, reveal,summarize,state,imply 等。","no":143},{"id":"1718789649051","type":"single","material":"","stem":"（）wasn't his opinion that the company picnic should be postponed because it looked like rain.","options":[{"label":"A","content":"They"},{"label":"B","content":"Its"},{"label":"C","content":"There"},{"label":"D","content":"It"}],"answer":"D","explanation":"首先，空格内应当填入的是主语，所以排除副词 there。再判断单复数，排除 they。在剩下的 it和its 中间选择 , 因为后面有 that 引导的从句，所以应该选择 it 做形式主语。its 是所有格，不能做句子的主语。","no":144},{"id":"1718789649052","type":"single","material":"","stem":"We will discuss it further（）Ms. Miller come here.","options":[{"label":"A","content":"because"},{"label":"B","content":"since"},{"label":"C","content":"should"},{"label":"D","content":"unless"}],"answer":"C","explanation":"空格内应填入 should。这里省略了 if 的虚拟条件倒装句。","no":145},{"id":"1718789649053","type":"single","material":"","stem":"<p>During the recession, it will be better to be（）prepared for the cutbacks in jobs. </p>","options":[{"label":"A","content":"sincerely"},{"label":"B","content":"bitterly"},{"label":"C","content":"tightly"},{"label":"D","content":"adequately"}],"answer":"D","explanation":"空格前是 be 动词，后面是形容词，空格处应填入副词来修饰。根据意思，最符合的是 D 选项， be adequately prepared for 意为“对...作充分的准备”。","no":146},{"id":"1718789649054","type":"single","material":"","stem":"The organization held special events to call（）to the needy children in isolated islands.","options":[{"label":"A","content":"highlight"},{"label":"B","content":"focus"},{"label":"C","content":"attention"},{"label":"D","content":"concentration"}],"answer":"C","explanation":"题目中经常会考到固定搭配，如果不知道其用法可就难办了。call attention to 意为“引起对某事的关心”。","no":147}]};
